using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class IncidentReview:Entity<Guid>{private IncidentReview(){}private IncidentReview(Guid id,Guid tenantId,Guid incidentId,Guid reporterId,Guid reviewerId,short resultingStateId,string resolution){if(tenantId==Guid.Empty||incidentId==Guid.Empty||reviewerId==Guid.Empty)throw new ArgumentException("Review references are required.");if(reporterId==reviewerId)throw new InvalidOperationException("Reporter cannot review own incident.");if(resultingStateId<=0)throw new ArgumentOutOfRangeException(nameof(resultingStateId));Id=id;TenantId=tenantId;IncidentId=incidentId;ReporterUserId=reporterId;ReviewerUserId=reviewerId;ResultingStateId=resultingStateId;Resolution=OperationRules.Text(resolution,4000);ReviewedAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid IncidentId{get;private set;}public Guid ReporterUserId{get;private set;}public Guid ReviewerUserId{get;private set;}public short ResultingStateId{get;private set;}public string Resolution{get;private set;}=string.Empty;public DateTimeOffset ReviewedAtUtc{get;private set;}public static IncidentReview Record(Guid tenantId,Guid incidentId,Guid reporterId,Guid reviewerId,short stateId,string resolution)=>new(Guid.NewGuid(),tenantId,incidentId,reporterId,reviewerId,stateId,resolution);}
